CREATE TABLE IF NOT EXISTS collections (id BIGSERIAL PRIMARY KEY, chain_address VARCHAR(128) NOT NULL UNIQUE, name VARCHAR(255), slug VARCHAR(255));
CREATE TABLE IF NOT EXISTS gifts (id BIGSERIAL PRIMARY KEY, canonical_id VARCHAR(255) NOT NULL UNIQUE, collection_id BIGINT REFERENCES collections(id), gift_number INTEGER, name VARCHAR(255), model VARCHAR(255), metadata_uri TEXT, image_url TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS listings (id BIGSERIAL PRIMARY KEY, gift_id BIGINT NOT NULL REFERENCES gifts(id), marketplace VARCHAR(64) NOT NULL, external_id VARCHAR(255) NOT NULL, price_ton NUMERIC(24,9) NOT NULL, seller VARCHAR(255), url TEXT, first_seen_at TIMESTAMPTZ NOT NULL, last_seen_at TIMESTAMPTZ NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT uq_listing_source_id UNIQUE (marketplace, external_id));
CREATE TABLE IF NOT EXISTS price_snapshots (id BIGSERIAL PRIMARY KEY, gift_id BIGINT NOT NULL REFERENCES gifts(id), marketplace VARCHAR(64) NOT NULL, observed_at TIMESTAMPTZ NOT NULL, floor_ton NUMERIC(24,9), median_ton NUMERIC(24,9), volume_ton NUMERIC(24,9), listings_count INTEGER NOT NULL DEFAULT 0, source_url TEXT);
CREATE INDEX IF NOT EXISTS ix_price_history_gift_market_time ON price_snapshots(gift_id, marketplace, observed_at);
CREATE TABLE IF NOT EXISTS trades (id BIGSERIAL PRIMARY KEY, gift_id BIGINT NOT NULL REFERENCES gifts(id), marketplace VARCHAR(64) NOT NULL, external_id VARCHAR(255) NOT NULL, price_ton NUMERIC(24,9) NOT NULL, seller VARCHAR(255), buyer VARCHAR(255), traded_at TIMESTAMPTZ NOT NULL, source_url TEXT, CONSTRAINT uq_trade_source_id UNIQUE (marketplace, external_id));
CREATE TABLE IF NOT EXISTS source_statuses (id BIGSERIAL PRIMARY KEY, marketplace VARCHAR(64) NOT NULL UNIQUE, status VARCHAR(32) NOT NULL, last_success_at TIMESTAMPTZ, last_attempt_at TIMESTAMPTZ NOT NULL, last_error TEXT, listings_count INTEGER NOT NULL DEFAULT 0);
